import sys, json, re
from pathlib import Path
sys.path.append('storage/shared')

from meta.prioritize_workflow import snapshot
from meta.diff_priorities_param import run as run_diff
from meta.simulate_scheduler_param import run as run_sim
try:
    from meta.friction import compute_friction
except Exception:
    compute_friction = None

WF = "doc_update_v75_80"

v4_path  = snapshot(WF, mode="v4")
v02_path = snapshot(WF, mode="v02")
diff_out = run_diff(WF)
sim_out  = run_sim(WF)

# Attempt to extract delta from the simulation MD
delta = None
try:
    md_path = Path(sim_out.get("artifact_md"))
    if md_path.exists():
        txt = md_path.read_text(encoding="utf-8")
        m = re.search(r"Delta\s*\(compare\s*-\s*baseline\)\s*:\s*([-\d\.]+)", txt)
        if m:
            delta = float(m.group(1))
except Exception:
    pass

fric = {}
if compute_friction:
    try:
        fric = compute_friction(WF)
    except Exception:
        fric = {}

print(json.dumps({
    "workflow": WF,
    "paths": {
        "v4": v4_path,
        "v02": v02_path,
        "diff_md": diff_out.get("out_md"),
        "sim_md": sim_out.get("artifact_md")
    },
    "delta_weighted_wait": delta,
    "friction_summary": fric
}, indent=2))

